void check(bool b,const char*m){if(!b)throw std::runtime_error(m);}
int main(){try{ActorView peer{2,HeroSpecies::Reedcrest,{6,0,0},0,5000,0,.2,.2,.2,true,Activity::Travel};auto d=reedPeerDecision({0,0,0},true,false,false,false,&peer);check(d.leader==ReedLeader::Partner&&d.heroTarget&&d.heroTarget->x==3,"partner leading target");check(reedPeerDecision({0,0,0},true,true,false,false,&peer).leader==ReedLeader::Hero,"direct role");check(!reedPeerDecision({0,0,0},true,false,true,false,&peer).heroTarget&&!reedPeerDecision({0,0,0},true,false,false,true,&peer).heroTarget,"player/need priority");check(!reedPeerDecision({-30,0,0},true,false,false,false,&peer).heroTarget&&!reedPeerDecision({0,4,0},true,false,false,false,&peer).heroTarget,"remote/vertical hero knowledge");peer.thirst=.8;check(reedPeerDecision({0,0,0},true,false,false,false,&peer).leader==ReedLeader::None,"partner urgent needs priority");peer.thirst=.2;
std::vector<HabitatSite> sites{{{0,0,0},false,true,{1,2}},{{10,0,0},true,false,{0}},{{-10,0,0},false,false,{0}}};Population p(42,1001,sites,1);auto state=p.snapshot();auto& a=state.actors[0];a.species=HeroSpecies::Reedcrest;a.calendarAge=5000;a.stage=LifeStage::Adult;a.site=0;a.target=1;a.position=sites[0].position;a.activity=Activity::Travel;a.hunger=.2;a.thirst=.2;a.fatigue=.2;a.isResting=false;p.restore(state);const Identity id=a.id;auto follows=p,leads=p;BodyAwareness context{{-12,0,0},{},id,3,false,true};follows.advance({1,2},false,context);context.peerLeads=true;leads.advance({1,2},false,context);check(follows.actors()[0].position.x<0&&leads.actors()[0].position.x>0,"actual partner follower/ordinary leader motion");check(leads.actors()[0].calendarAge==5002&&follows.actors()[0].calendarAge==5002,"double lifecycle clock");
a.activity=Activity::Drink;a.target=0;a.thirst=.8;p.restore(state);ResourceLedgerDto ledger{{{100,ResourceKind::Creek,10,2},{200,ResourceKind::Shrub,10,1}},{{90,100,2},{91,200,1}}};uint64_t next=100;engine::NativePopulationRegistry host(p,ledger,{},{{0,100,sites[0].position},{1,200,sites[1].position}},next);const auto bindings=host.sessions();context={{-2,0,0},{},id,3,true,true};host.advance({1,2},true,context,true);check(host.events().size()==1&&host.events()[0].resource==100&&host.events()[0].amount>.0099,"urgent bonded partner cannot really drink near hero");check(host.snapshot().actors[0].thirst<.8004&&host.snapshot().actors[0].calendarAge==5002,"accepted relief/clock");check(host.sessions()==bindings&&host.ledger().sessions.size()==3&&host.ledger().resources[1].consumedQuantity==1,"session/history preservation");auto before=host.snapshot();const auto history=host.ledger();host.advanceDormant({3,4});check(host.events().empty()&&host.snapshot().actors[0].calendarAge==5006&&host.snapshot().actors[0].position.x==before.actors[0].position.x&&host.ledger().sessions.size()==history.sessions.size(),"dormant camera cannot activate/move/contact");
auto midpoint=state;midpoint.actors[0].site=1;midpoint.actors[0].target=0;midpoint.actors[0].position={3,0,0};midpoint.actors[0].activity=Activity::Travel;midpoint.actors[0].thirst=.2;p.restore(midpoint);BodyAwareness reverse{{8,0,0},{},id,3,false,true};p.advance({1,1},false,reverse);auto reversed=p.snapshot();check(reversed.actors[0].position.x>3&&reversed.actors[0].site==0&&reversed.actors[0].target==1,"in-flight partner failed exact-edge reverse");p.restore(reversed);for(int i=0;i<50;++i)p.advance({1,1},false,reverse);check(std::abs(p.actors()[0].position.x-5)<1e-8,"in-flight partner crossed wait radius");p.restore(p.snapshot());
p.restore(midpoint);BodyAwareness legacyFlags{{8,0,0},{},id,3};const double oldDistance=p.actors()[0].distanceTravelledMeters;p.advance({1,1},false,legacyFlags);check(p.actors()[0].position.x<3&&std::abs(p.actors()[0].distanceTravelledMeters-oldDistance-.7)<1e-8,"default false changed inherited in-flight behavior");p.restore(midpoint);uint64_t reverseNext=100;engine::NativePopulationRegistry reverseHost(p,ledger,{},{{0,100,sites[0].position},{1,200,sites[1].position}},reverseNext);auto reverseBindings=reverseHost.sessions();const auto reverseAge=reverseHost.actors()[0].calendarAge;reverseHost.advance({1,1},true,reverse);reverseHost.registry().snapshot(1001);auto validReverse=reverseHost.snapshot();Population validate(42,1001,sites,0);validate.restore(validReverse);for(int i=0;i<50;++i)reverseHost.advance({1,1},true,reverse);validate.restore(reverseHost.snapshot());check(reverseHost.actors()[0].id==id&&reverseHost.actors()[0].calendarAge==reverseAge+51&&std::abs(reverseHost.actors()[0].position.x-5)<1e-8,"registry reverse/wait identity age jumps");check(std::abs(reverseHost.actors()[0].distanceTravelledMeters-midpoint.actors[0].distanceTravelledMeters-2)<1e-8,"reverse/wait accumulated distance jump");auto reverseHistory=reverseHost.ledger();check(reverseHost.sessions()==reverseBindings&&reverseHistory.sessions.size()==2&&reverseHistory.sessions[0].amount==2&&reverseHistory.sessions[1].amount==1&&reverseHistory.resources[0].consumedQuantity==2&&reverseHistory.resources[1].consumedQuantity==1,"reverse/wait history mutated");
PeerCompanionship bond;std::vector<ActorView> actors{peer};for(int i=0;i<20;++i)bond.update(1,HeroSpecies::Reedcrest,{0,0,0},true,.1,i*.1,actors);check(bond.peer()==2,"actual body encounter did not bond");bond.update(1,HeroSpecies::Reedcrest,{-30,0,0},true,.1,3,actors);check(bond.peer()==2&&!bond.present(),"separation lost retained identity");bond.update(1,HeroSpecies::Reedcrest,{0,0,0},true,.1,4,actors);check(bond.present()&&bond.peer()==2,"reunion wrong identity");bond=PeerCompanionship{};check(!bond.peer(),"new life inherits peer");HeroSim hero;check(HeroDestination::submit(hero,{0,0,0},*d.heroTarget,true),"single destination owner");hero.setDirect(true);check(!HeroDestination::active(hero),"direct cannot interrupt hero follow");std::cout<<"REED_REVIEW_OK reciprocal_registry_motion_onceclock_urgentcontact_history_roles_sense_separation_reunion_newlife_direct\n";}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}



